-- 027 · Правила категоризации переезжают из кода в базу
-- ADR-0010, TASK-022.
--
-- В `src/lib/categorize.js` лежало 70 правил с фамилиями арендодателя,
-- бухгалтера и учредителей, названием своего ТОО, адресом и поставщиками
-- Алматы. При продаже другому заведению всё это уехало бы в его репозиторий.
--
-- Движок правил из базы уже был и применяется раньше встроенных, поэтому
-- перенос не меняет логику. Шаблоны сохранены как есть, оператором `matches`:
-- переписывание их в `contains` изменило бы поведение.
--
-- Совпадение проверено контрольной суммой по (поле|шаблон|категория|
-- направление|доп. поле|доп. шаблон): md5 совпал у кода и у базы —
-- 5966672aa4670e4f830724be49bc35cc.
--
-- Правила, заведённые пользователем через интерфейс, имеют sort_order = 0 и
-- остаются выше перенесённых — их приоритет не меняется.

-- 1. Порядок правил ---------------------------------------------------------
-- Выигрывает первое совпавшее, поэтому порядок обязан быть определённым.
-- До этой миграции правила читались без сортировки вообще.

ALTER TABLE public.bank_rules
  ADD COLUMN IF NOT EXISTS sort_order INTEGER NOT NULL DEFAULT 0;

-- 2. Условия: направление операции и регулярные выражения --------------------

ALTER TABLE public.bank_rule_conditions DROP CONSTRAINT IF EXISTS bank_rule_conditions_field_check;
ALTER TABLE public.bank_rule_conditions ADD CONSTRAINT bank_rule_conditions_field_check
  CHECK (field IN ('beneficiary', 'purpose', 'knp', 'amount', 'is_debit'));

ALTER TABLE public.bank_rule_conditions DROP CONSTRAINT IF EXISTS bank_rule_conditions_operator_check;
ALTER TABLE public.bank_rule_conditions ADD CONSTRAINT bank_rule_conditions_operator_check
  CHECK (operator IN ('contains', 'not_contains', 'equals', 'not_equals', 'starts_with',
                      'matches', 'gt', 'gte', 'lt', 'lte', 'between'));

-- 3. Перенесённые правила ----------------------------------------------------
-- Порядок сохранён: sort_order 10, 20, … в порядке прежнего массива.
-- У правила «аренд» есть второе условие по получателю: аренда засчитывается
-- только платежам арендодателю (решение 04.09.2026).
-- Повторный запуск ничего не задваивает.

