    AS x(ord int, name text, category text, field text, pattern text, is_debit text,
         extra_field text, extra_pattern text)
  WHERE NOT EXISTS (SELECT 1 FROM public.bank_rules WHERE sort_order > 0)
), ins AS (
  INSERT INTO public.bank_rules (name, logic, category_code, action, sort_order)
  SELECT name, 'and', category, 'categorize', ord FROM src
  RETURNING id, sort_order
)
INSERT INTO public.bank_rule_conditions (rule_id, field, operator, value, sort_order)
SELECT i.id, s.field, 'matches', s.pattern, 0 FROM ins i JOIN src s ON s.ord = i.sort_order
UNION ALL
SELECT i.id, 'is_debit', 'equals', s.is_debit, 1 FROM ins i JOIN src s ON s.ord = i.sort_order
  WHERE s.is_debit IS NOT NULL
UNION ALL
SELECT i.id, s.extra_field, 'matches', s.extra_pattern, 2 FROM ins i JOIN src s ON s.ord = i.sort_order
  WHERE s.extra_field IS NOT NULL;
